#!/usr/bin/env bash
# gen_cask.sh — render the Homebrew cask for a ClashGO release.
#
#   tools/gen_cask.sh <version> <ClashGO.dmg> <out.rb> [owner/repo]
#
# The cask pins the DMG's SHA-256 so `brew fetch`/`brew install` verify the
# download. Called by `make brew-cask` (and therefore `make release`) and by
# the release workflow, which uploads the result as a release asset and syncs
# it to the Homebrew tap.
#
# The checked-in Casks/clashgo.rb is the last published release; treat it as a
# generated file and regenerate it on every release instead of editing it.

set -euo pipefail

if [[ $# -lt 3 ]]; then
  cat >&2 <<EOF
usage: $(basename "$0") <version> <ClashGO.dmg> <out.rb> [owner/repo]

  <version>     release version without the leading v (e.g. 1.0.0)
  <ClashGO.dmg> DMG whose SHA-256 is pinned in the cask
  <out.rb>      output path for the rendered cask
EOF
  exit 64
fi

VERSION="${1#v}"
DMG="$2"
OUT="$3"
REPO="${4:-DSargent21/ClashGo}"

[[ -f "$DMG" ]] || { echo "error: DMG not found: $DMG" >&2; exit 66; }
[[ "$VERSION" =~ ^[0-9]+\.[0-9]+\.[0-9]+([.-][0-9A-Za-z.]+)?$ ]] \
  || { echo "error: unexpected version '$VERSION'" >&2; exit 64; }

SHA="$(shasum -a 256 "$DMG" | awk '{ print $1 }')"

mkdir -p "$(dirname "$OUT")"
cat > "$OUT" <<EOF
# Generated by tools/gen_cask.sh from ClashGO v$VERSION — do not edit by hand.
# Install: brew install --cask dsargent21/tap/clashgo
# Upgrade: brew upgrade --cask clashgo
cask "clashgo" do
  version "$VERSION"
  sha256 "$SHA"

  url "https://github.com/$REPO/releases/download/v#{version}/ClashGO.dmg"
  name "ClashGO"
  desc "Clash of Clans automation engine with desktop GUI and headless CLI"
  homepage "https://github.com/$REPO"

  livecheck do
    url "https://github.com/$REPO/releases/latest/download/latest.json"
    strategy :json do |json|
      json["version"]
    end
  end

  depends_on arch: :arm64

  app "ClashGO.app"

  zap trash: "~/Library/Application Support/ClashGO"
end
EOF

echo "wrote $OUT (clashgo $VERSION, sha256 ${SHA:0:12}…)" >&2
